#!/bin/bash
# PreToolUse hook (matcher Agent|SendMessage|Edit|Write|MultiEdit) for the research-kit
# ledger. Does nothing unless <project>/pm/ledger.jsonl exists, or the project is a linked
# worktree (.git file naming .git/worktrees/) whose `rk list` finds the main ledger. Never
# allows anything: it denies or stays silent (the normal permission flow continues).
#  - Edit/Write/MultiEdit of pm/ledger.jsonl or pm/STATUS.md: deny; only rk.py writes them.
#    Same for pm/stages/<one folder>/LEDGER.md (generated by stage-close only).
#  - Agent prompt / SendMessage message with a DELIVERABLE: line (a team brief): rk.py
#    brief-check; refused -> deny with its text. A passing brief marks its task running.
#    Not checked inside a subagent (.agent_id set): only the lead hands out work.
# Thin wrapper (D-131): the rules live in rk_hook.py (ledger-guard); this file only finds
# a Python 3. Without one: a systemMessage warning (exit 0), the guard is OFF.
case "$0" in */*) here="${0%/*}" ;; *) here=. ;; esac
. "$here/find-python.sh"
rk_find_python || rk_no_python_guard
exec "${RK_PY[@]}" -I "$here/rk_hook.py" ledger-guard
